def is_each_letter_increasing(s):
    letters = []
    for ch in s:
        if ch.isalpha():
            letters.append(ch.lower())
    for i in range(1, len(letters)):
        if letters[i] <= letters[i - 1]:
            return False
    return True

def is_isogram(s):
    seen_letters = set()
    for ch in s:
        if ch.isalpha():
            lower_ch = ch.lower()
            if lower_ch in seen_letters:
                return False
            seen_letters.add(lower_ch)
    return True

def is_valid_utc_offset(s):
    if len(s) != 6:
        return False
    sign = s[0]
    if sign not in '+-':
        return False
    hh = s[1:3]
    colon = s[3]
    mm = s[4:6]
    if colon != ':':
        return False
    if not (hh.isdigit() and mm.isdigit()):
        return False
    hours = int(hh)
    minutes = int(mm)
    if minutes > 59:
        return False
    total = hours * 60 + minutes
    if sign == '-':
        total = -total
    return -720 <= total <= 840

