def split_keep_delimiters(s, delims):
    delim_set = set(delims)
    tokens = []
    buf = ""
    for ch in s:
        if ch in delim_set:
            if buf:
                tokens.append(buf)
                buf = ""
            tokens.append(ch)
        else:
            buf += ch
    if buf:
        tokens.append(buf)
    return tokens

