def swap_adjacent_pairs(s):
    chars = list(s)
    i = 0
    while i + 1 < len(chars):
        chars[i], chars[i + 1] = chars[i + 1], chars[i]
        i += 2
    return ''.join(chars)

def count_word_trigrams(words):
    result = {}
    n = len(words)
    for i in range(n - 2):
        key = (words[i], words[i + 1], words[i + 2])
        result[key] = result.get(key, 0) + 1
    return result

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

