def is_valid_datetime_string(s):
    if not isinstance(s, str) or len(s) != 19:
        return False
    if s[4] != '-' or s[7] != '-' or s[10] != ' ' or s[13] != ':' or s[16] != ':':
        return False
    y, mo, d, h, mi, sec = s[0:4], s[5:7], s[8:10], s[11:13], s[14:16], s[17:19]
    parts = [y, mo, d, h, mi, sec]
    if not all(p.isdigit() for p in parts):
        return False
    y, mo, d, h, mi, sec = int(y), int(mo), int(d), int(h), int(mi), int(sec)
    if mo < 1 or mo > 12:
        return False
    leap = y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    days_in_month = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if d < 1 or d > days_in_month[mo - 1]:
        return False
    return 0 <= h <= 23 and 0 <= mi <= 59 and 0 <= sec <= 59

