def prime_gap(n):
    def is_prime(x):
        if x < 2:
            return False
        for d in range(2, int(x ** 0.5) + 1):
            if x % d == 0:
                return False
        return True
    primes = []
    candidate = 2
    while len(primes) <= n:
        if is_prime(candidate):
            primes.append(candidate)
        candidate += 1
    return primes[n] - primes[n - 1]

