def add_weeks_to_date(y, m, d, n_weeks):
    def is_leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    def days_in_month(year, month):
        lengths = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return lengths[month - 1]

    total_days = n_weeks * 7
    if total_days >= 0:
        remaining = total_days
        while remaining > 0:
            dim = days_in_month(y, m)
            if d + remaining <= dim:
                d += remaining
                remaining = 0
            else:
                remaining -= (dim - d + 1)
                d = 1
                m += 1
                if m > 12:
                    m = 1
                    y += 1
    else:
        remaining = -total_days
        while remaining > 0:
            if d - remaining >= 1:
                d -= remaining
                remaining = 0
            else:
                remaining -= d
                m -= 1
                if m < 1:
                    m = 12
                    y -= 1
                d = days_in_month(y, m)
    return (y, m, d)

